            prev_bids.append(prev['bid'])

    if no_water > 0:
        # Desperate: need water
        base_bid = DAILY_SALARY * 0.9
        if hp <= 2:
            base_bid = DAILY_SALARY * 0.95
        return min(budget, base_bid)
